-- Блок меняется только если лежит в том виде, в каком его оставила миграция 0046 (по md5); правки из админки не затираются.
-- Откат: supabase/rollback/0047_home_diagnostic_score_down.sql
update public.content_blocks
   set data = $j$[{"n":"01","icon":"target","t":"Диагностика","d":"8–12 заданий по предмету, 7–10 минут, без подсказок. В конце ты видишь свой уровень, сильные и слабые темы и примерный балл: это прогноз по короткой диагностике, а не гарантия результата."},{"n":"02","icon":"book","t":"Персональный план","d":"На основе результатов — что повторить сегодня, сколько тренировок на неделе и когда пробник."},{"n":"03","icon":"chat","t":"Тренировки с ИИ","d":"Решаешь задания ФИПИ, при затруднении — уровневые подсказки и объяснение темы, без готового ответа."},{"n":"04","icon":"timer","t":"Пробный вариант","d":"Часть 1 и часть 2 на время, без подсказок — как на настоящем экзамене. Разбор после сдачи."}]$j$::jsonb, updated_at = now()
 where key = 'process'
